// @FIGURE_CODE_BEGIN
(function(){
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 750, 420);

var AX = 200, AY = 350;
var GX = 650, GY = 350;
var BY = 100;
var SX = 55;

var apexX = 1.5;
var altShown = false;

var dyn = draw.group();
var ovl = draw.group();

// Persistent click area on base
var baseClick = ovl.rect(520, 36).attr({x:140, y:332, fill:'transparent', cursor:'pointer'});
baseClick.on('click', function(){ trigger_altitudeState(); });
baseClick.on('mousemove', function(e){ showTooltip('Click to construct/drop the altitude h', e); });
baseClick.on('mouseleave', function(){ hideTooltip(); });

function betaX(){ return AX + apexX * SX; }

function redraw(){
  dyn.clear();
  var bx = betaX(), by = BY;
  var fx = bx, fy = AY;
  var obtuse = apexX < 0;

  // Dashed extension (obtuse)
  if(obtuse){
    dyn.line(fx - 30, AY, AX, AY).stroke({color:'#555', width:1.5, dasharray:'7,5'});
  }

  // Base b
  dyn.line(AX, AY, GX, GY).stroke({color:'#000', width:2.2});

  // Side c
  dyn.line(AX, AY, bx, by).stroke({color:'#000', width:2.2});

  // Side a
  dyn.line(bx, by, GX, GY).stroke({color:'#000', width:2.2});

  // Altitude
  if(altShown){
    dyn.line(bx, by, fx, fy).stroke({color:'#555', width:1.5, dasharray:'7,5'});
    // Right-angle square
    var sq = 13;
    dyn.path('M '+(fx+sq)+' '+fy+' L '+(fx+sq)+' '+(fy-sq)+' L '+fx+' '+(fy-sq))
      .fill('none').stroke({color:'#000', width:1.2});
    // h label
    var hlx = bx + 12, hly = (by + fy)/2;
    dyn.text('h').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
      .attr({x:hlx, y:hly, 'text-anchor':'start'});
    // Area formula
    dyn.text('Area = ½ · b · c · sin α').font({family:'Georgia,serif', size:15, fill:'#222'})
      .attr({x:320, y:28, 'text-anchor':'middle'})
      .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round'});
  }

  // Angle arcs
  var svgAng = Math.atan2(by - AY, bx - AX);
  var r1 = 32, r2 = 44;

  if(!obtuse){
    // Interior angle α arc
    var sx1 = AX + r1, sy1 = AY;
    var ex1 = AX + r1*Math.cos(svgAng), ey1 = AY + r1*Math.sin(svgAng);
    var la = Math.abs(svgAng) > Math.PI ? 1 : 0;
    dyn.path('M '+sx1+' '+sy1+' A '+r1+' '+r1+' 0 '+la+' 0 '+ex1+' '+ey1)
      .fill('none').stroke({color:'#c00', width:1.8});
    // α label
    var la2 = svgAng/2;
    var lx = AX + (r1+16)*Math.cos(la2), ly = AY + (r1+16)*Math.sin(la2);
    dyn.text('α').font({family:'Georgia,serif', style:'italic', size:15, fill:'#c00'})
      .attr({x:lx, y:ly+5, 'text-anchor':'middle'});
  } else {
    // Interior angle α (obtuse) with larger radius
    var sx2 = AX + r2, sy2 = AY;
    var ex2 = AX + r2*Math.cos(svgAng), ey2 = AY + r2*Math.sin(svgAng);
    var la3 = Math.abs(svgAng) > Math.PI ? 1 : 0;
    dyn.path('M '+sx2+' '+sy2+' A '+r2+' '+r2+' 0 '+la3+' 0 '+ex2+' '+ey2)
      .fill('none').stroke({color:'#c00', width:1.8});
    // α label
    var la4 = svgAng/2;
    var lx2 = AX + (r2+16)*Math.cos(la4), ly2 = AY + (r2+16)*Math.sin(la4);
    dyn.text('α').font({family:'Georgia,serif', style:'italic', size:15, fill:'#c00'})
      .attr({x:lx2, y:ly2+5, 'text-anchor':'middle'});

    // Exterior angle α′ arc
    var extA = -Math.PI;
    var sx3 = AX + r1*Math.cos(extA), sy3 = AY + r1*Math.sin(extA);
    var ex3 = AX + r1*Math.cos(svgAng), ey3 = AY + r1*Math.sin(svgAng);
    dyn.path('M '+sx3+' '+sy3+' A '+r1+' '+r1+' 0 0 1 '+ex3+' '+ey3)
      .fill('none').stroke({color:'#c00', width:1.8});
    // α′ label
    var midExt = (extA + svgAng)/2;
    var lx3 = AX + (r1+16)*Math.cos(midExt), ly3 = AY + (r1+16)*Math.sin(midExt);
    dyn.text("α′").font({family:'Georgia,serif', style:'italic', size:14, fill:'#c00'})
      .attr({x:lx3, y:ly3+5, 'text-anchor':'middle'});
  }

  // Vertex labels
  dyn.text('α').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:AX-22, y:AY+8, 'text-anchor':'middle'});
  dyn.text('β').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:bx, y:by-14, 'text-anchor':'middle'});
  dyn.text('γ').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:GX+18, y:GY+8, 'text-anchor':'middle'});

  // Side label b
  dyn.text('b').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:(AX+GX)/2, y:AY+28, 'text-anchor':'middle'});

  // Side label c (perpendicular offset)
  var dcx = bx - AX, dcy = by - AY;
  var dcl = Math.sqrt(dcx*dcx + dcy*dcy) || 1;
  var cox = (dcy/dcl)*16, coy = (-dcx/dcl)*16;
  dyn.text('c').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:(AX+bx)/2 + cox, y:(AY+by)/2 + coy + 5, 'text-anchor':'middle'});

  // Side label a (perpendicular offset)
  var dax = GX - bx, day = GY - by;
  var dal = Math.sqrt(dax*dax + day*day) || 1;
  var aox = (day/dal)*16, aoy = (-dax/dal)*16;
  dyn.text('a').font({family:'Georgia,serif', style:'italic', size:17, fill:'#000'})
    .attr({x:(bx+GX)/2 + aox, y:(by+GY)/2 + aoy + 5, 'text-anchor':'middle'});

  // Hover on triangle
  var triPath = dyn.polygon([[AX,AY],[bx,by],[GX,GY]])
    .fill({color:'#000', opacity:0}).stroke({width:0});
  triPath.css('cursor','pointer');
  triPath.on('mousemove', function(e){
    var ang = Math.abs(Math.atan2(AY-by, bx-AX)*180/Math.PI);
    var c = Math.sqrt((bx-AX)*(bx-AX)+(by-AY)*(by-AY));
    var h = c * Math.sin(ang*Math.PI/180);
    showTooltip('α ≈ '+ang.toFixed(1)+'°  |  h = c·sin α ≈ '+h.toFixed(2), e);
  });
  triPath.on('mouseleave', function(){ hideTooltip(); });
  triPath.on('click', function(){
    showPopup('Oblique Triangle Area',
      'The area equals ½·b·h where h is the perpendicular from β to line b. Since h = c·sin α (the leg opposite α in the right triangle formed by the altitude), we get Area = ½·b·c·sin α. This holds whether α is acute or obtuse because sin(180°−α) = sin α.');
  });
}

