    state:{ caseView:false, apexPosition:1.5, altitudeState:true } },
  { title:'Obtuse arrangement',
    narration:'Snapping to the obtuse case moves β left of α; the altitude foot now falls outside the triangle on the dashed base extension, and the relevant angle is the exterior α′ = 180° − α, yet sin α′ = sin α so the formula is unchanged.',
    state:{ caseView:true, apexPosition:-1.2, altitudeState:true } },
  { title:'Sweep the apex',
    narration:'Drag β continuously across α and watch the foot slide from the interior of b onto the extension while the labeled angle flips from α to α′ — one height construction serves every oblique triangle.',
    state:{ caseView:false, apexPosition:0.2, altitudeState:true } }
];
var curStep = 0;

function applyStep(i){
  curStep = i;
  var s = steps[i];
  apexX = s.state.apexPosition;
  altShown = s.state.altitudeState;
  document.getElementById('apexPositionInput').value = apexX;
  document.getElementById('apexPositionVal').value = apexX.toFixed(1);
  document.getElementById('caseViewInput').checked = s.state.caseView;
