(function(){
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 900, 420);

var altShown = true;
var showObtuse = true;
var apexPos = 1.5;

var dyn = draw.group();

function drawTriangle(ax, ay, gx, gy, bx, by, showAlt, showExtAngle) {
    var footX = bx, footY = ay;
    var isObtuse = bx < ax;

    // Dashed extension of base (obtuse only)
    if (isObtuse) {
        dyn.line(footX - 15, ay, ax, ay)
            .stroke({color:'#000', width:1.5, dasharray:'6,4'});
    }

    // Base b
    dyn.line(ax, ay, gx, gy).stroke({color:'#000', width:2});
    // Side c
    dyn.line(ax, ay, bx, by).stroke({color:'#000', width:2});
    // Side a
    dyn.line(bx, by, gx, gy).stroke({color:'#000', width:2});

    // Altitude h
    if (showAlt) {
        dyn.line(bx, by, footX, footY)
            .stroke({color:'#000', width:1.5, dasharray:'6,4'});
        var sq = 11;
        dyn.path('M '+(footX+sq)+' '+footY+' L '+(footX+sq)+' '+(footY-sq)+' L '+footX+' '+(footY-sq))
            .fill('none').stroke({color:'#000', width:1.2});
        // h label
        var hlx = bx + 10, hly = (by + footY) / 2;
        dyn.text('h').font({family:'Georgia,serif', style:'italic', size:15, fill:'#000'})
            .attr({x: hlx, y: hly, 'text-anchor':'start'});
    }

    // Angle arcs
    var angToBeta = Math.atan2(by - ay, bx - ax);
    var r1 = 28, r2 = 38;

    if (!isObtuse) {
        // Acute interior angle arc
        var sx = ax + r1, sy = ay;
        var ex = ax + r1 * Math.cos(angToBeta), ey = ay + r1 * Math.sin(angToBeta);
        dyn.path('M '+sx+' '+sy+' A '+r1+' '+r1+' 0 0 0 '+ex+' '+ey)
            .fill('none').stroke({color:'#000', width:1.5});
    } else {
        // Obtuse: interior angle arc (larger radius)
        var sx2 = ax + r2, sy2 = ay;
        var ex2 = ax + r2 * Math.cos(angToBeta), ey2 = ay + r2 * Math.sin(angToBeta);
        dyn.path('M '+sx2+' '+sy2+' A '+r2+' '+r2+' 0 0 0 '+ex2+' '+ey2)
            .fill('none').stroke({color:'#000', width:1.5});

        // Exterior angle α′ arc (from leftward to side c)
        var extA = Math.PI;
        var sx3 = ax + r1 * Math.cos(extA), sy3 = ay + r1 * Math.sin(extA);
        var ex3 = ax + r1 * Math.cos(angToBeta), ey3 = ay + r1 * Math.sin(angToBeta);
        dyn.path('M '+sx3+' '+sy3+' A '+r1+' '+r1+' 0 0 1 '+ex3+' '+ey3)
            .fill('none').stroke({color:'#000', width:1.5});

        // α′ label
        var midExt = (extA + angToBeta) / 2;
        if (midExt > Math.PI) midExt -= 2 * Math.PI;
        var lx3 = ax + (r1 + 13) * Math.cos(midExt);
        var ly3 = ay + (r1 + 13) * Math.sin(midExt);
        dyn.text("\u03B1\u2032").font({family:'Georgia,serif', style:'italic', size:13, fill:'#000'})
            .attr({x: lx3, y: ly3 + 4, 'text-anchor':'middle'});

        // α label for interior angle (right side)
        var midInt = angToBeta / 2;
        var lx4 = ax + (r2 + 14) * Math.cos(midInt);
        var ly4 = ay + (r2 + 14) * Math.sin(midInt);
        dyn.text('\u03B1').font({family:'Georgia,serif', style:'italic', size:13, fill:'#000'})
            .attr({x: lx4 + 8, y: ly4 + 4, 'text-anchor':'middle'});
    }

    // Vertex labels
    dyn.text('\u03B1').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: ax - 18, y: ay + 7, 'text-anchor':'middle'});
    dyn.text('\u03B2').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: bx, y: by - 12, 'text-anchor':'middle'});
    dyn.text('\u03B3').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: gx + 16, y: gy + 7, 'text-anchor':'middle'});

    // Side label b
    dyn.text('b').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: (ax + gx) / 2, y: ay + 26, 'text-anchor':'middle'});

    // Side label c
    var dcx = bx - ax, dcy = by - ay;
    var dcl = Math.sqrt(dcx*dcx + dcy*dcy) || 1;
    var cox = (dcy / dcl) * 14, coy = (-dcx / dcl) * 14;
    dyn.text('c').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: (ax + bx)/2 + cox, y: (ay + by)/2 + coy + 5, 'text-anchor':'middle'});

    // Side label a
    var dax = gx - bx, day = gy - by;
    var dal = Math.sqrt(dax*dax + day*day) || 1;
    var aox = (day / dal) * 14, aoy = (-dax / dal) * 14;
    dyn.text('a').font({family:'Georgia,serif', style:'italic', size:16, fill:'#000'})
        .attr({x: (bx + gx)/2 + aox, y: (by + gy)/2 + aoy + 5, 'text-anchor':'middle'});
}

function redraw() {
    dyn.clear();

    // Left panel: acute triangle (apex right of α)
    var lax = 80, lay = 350, lgx = 400, lgy = 350;
    var lbx = lax + apexPos * 60, lby = 70;
    drawTriangle(lax, lay, lgx, lgy, lbx, lby, altShown, false);

    // Right panel: obtuse triangle (apex left of α)
    if (showObtuse) {
        var rax = 560, ray = 350, rgx = 860, rgy = 350;
        var rbx = rax - 25, rby = 60;
        drawTriangle(rax, ray, rgx, rgy, rbx, rby, altShown, true);
    }

    // Area formula
    if (altShown) {
        dyn.text('Area = \u00BD \u00B7 b \u00B7 c \u00B7 sin \u03B1')
            .font({family:'Georgia,serif', size:14, fill:'#000'})
            .attr({x: 450, y: 24, 'text-anchor':'middle'})
            .attr({'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round'});
    }
}

window.update_apexPosition = function(v) {
    apexPos = v;
    redraw();
};

window.toggle_caseView = function(on) {
    showObtuse = on;
    redraw();
};

window.trigger_altitudeState = function() {
    altShown = !altShown;
    document.getElementById('altitudeStateBtn').textContent = altShown ? 'Remove altitude h' : 'Construct altitude h';
    redraw();
};

var steps = [
    { narration: 'Both cases shown: the dashed altitude h from β meets the base (left, acute) or its extension (right, obtuse). In both, h = c\u00B7sin α.',
      state: { apexPosition: 1.5, caseView: true, altitudeState: true } },
    { narration: 'Acute case: the foot of h lands on segment b. In the right triangle formed, h is opposite α with hypotenuse c, so h = c\u00B7sin α and Area = \u00BD\u00B7b\u00B7c\u00B7sin α.',
      state: { apexPosition: 1.5, caseView: true, altitudeState: true } },
    { narration: 'Obtuse case: the foot falls on the dashed extension left of α. The relevant angle is the exterior α\u2032 = 180\u00B0 \u2212 α, but sin α\u2032 = sin α, so the formula is unchanged.',
      state: { apexPosition: 1.5, caseView: true, altitudeState: true } },
    { narration: 'Drag the slider to sweep β across α: watch the foot slide from the interior of b onto the extension while the labeled angle flips from α to α\u2032 \u2014 one construction serves every oblique triangle.',
      state: { apexPosition: 0.2, caseView: true, altitudeState: true } }
];
var curStep = 0;

function applyStep(i) {
    curStep = i;
    var s = steps[i];
    apexPos = s.state.apexPosition;
    showObtuse = s.state.caseView;
    altShown = s.state.altitudeState;
    document.getElementById('apexPositionInput').value = apexPos;
    document.getElementById('apexPositionVal').value = apexPos.toFixed(1);
    document.getElementById('caseViewInput').checked = showObtuse;
    document.getElementById('altitudeStateBtn').textContent = altShown ? 'Remove altitude h' : 'Construct altitude h';
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent = (i+1) + ' / ' + steps.length;
    redraw();
}

window.nextStep = function(){ applyStep(Math.min(curStep+1, steps.length-1)); };
window.prevStep = function(){ applyStep(Math.max(curStep-1, 0)); };

applyStep(0);
window.__markRendered();
})();
